import{_ as e,o as n,c as s,am as t}from"./chunks/framework._FJXuPhs.js";const b=JSON.parse('{"title":"常见生产问题","description":"","frontmatter":{"title":"常见生产问题","excerpt":"摘要","date":"2026-01-14 19:42:40","updated":"2026-01-14 19:42:40"},"headers":[],"relativePath":"中间件/中间件 - 消息队列/MQ RabbitMQ/常见生产问题.md","filePath":"中间件/中间件 - 消息队列/MQ RabbitMQ/常见生产问题.md","lastUpdated":null}'),l={name:"中间件/中间件 - 消息队列/MQ RabbitMQ/常见生产问题.md"};function i(p,a,o,c,r,u){return n(),s("div",null,[...a[0]||(a[0]=[t(`<h4 id="如何消息不丢失" tabindex="-1">如何消息不丢失 <a class="header-anchor" href="#如何消息不丢失" aria-label="Permalink to &quot;如何消息不丢失&quot;">​</a></h4><p>一般来说，在以下几种情况下都有可能发生消息丢失的情况</p><ul><li>1、消息未到达交换机</li><li>2、消息未到达队列</li><li>3、队列中消息丢失</li><li>4、消费者未接收到消息</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402271502394.png" alt="image.png"></p><p>RabbitMQ提供了多种机制来确保<strong>消息在传递过程中不丢失</strong>，主要通过以下几个方面实现</p><h5 id="发布确认" tabindex="-1">发布确认 <a class="header-anchor" href="#发布确认" aria-label="Permalink to &quot;发布确认&quot;">​</a></h5><p>发布确认（Publisher Confirms）</p><p>发布确认是RabbitMQ提供的一种轻量级、高效的保证消息不丢失的机制，相比事务机制有更好的性能。生产者可以在发送消息后异步接收一个来自RabbitMQ的确认，表明消息已被RabbitMQ正确接收。如果RabbitMQ没有确认消息，生产者可以选择重试发送消息。</p><ul><li>开启发布确认模式，首先需要将信道（Channel）设置为发布确认模式（<code>confirmSelect</code>）。</li><li>发送消息后，通过监听信道上的确认回调来检查消息是否被成功接收。</li></ul><p>如果开启发布确认模式后，当生产者发送消息到交换机或者队列失败会返回不同的信息给生产者</p><p>发送失败之后的处理方式：</p><ul><li>1、回调方法即时重发</li><li>2、记录日志</li><li>3、保存到数据库进行定时重发，重发后修改标识或者删除记录</li></ul><h5 id="消息持久化" tabindex="-1">消息持久化 <a class="header-anchor" href="#消息持久化" aria-label="Permalink to &quot;消息持久化&quot;">​</a></h5><p>为了防止消息中间件服务宕机造成的消息丢失，可以使用消息持久化避免。</p><p>消息持久化是防止消息丢失的重要手段之一。在RabbitMQ中，可以将队列（Queue）和消息（Message）设置为持久化，以确保即使在RabbitMQ服务器重启的情况下，消息也不会丢失。</p><ul><li><strong>持久化队列</strong>：在创建队列时，将其声明为持久化（durable）。这样，队列的元数据和状态会被保存到磁盘上。</li><li><strong>持久化消息</strong>：发送消息时，将消息的<code>delivery_mode</code>属性设置为<code>2</code>（表示持久化消息）。这样，消息会被写入到磁盘上，直到被完全消费。</li></ul><p>消息持久化：如果需要开启持久化，可以将交换机、队列、消息都进行持久化操作。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402271510090.png" alt="image.png"></p><h5 id="消费者确认" tabindex="-1">消费者确认 <a class="header-anchor" href="#消费者确认" aria-label="Permalink to &quot;消费者确认&quot;">​</a></h5><p>消费者确认（Consumer Acknowledgements）</p><p>为了防止队列到消费者这一步中消息丢失，可以开启消费者确认机制，</p><p>消费者确认（ACK）机制确保消息被消费者正确处理。在消费者成功处理消息后，它会发送一个ACK给RabbitMQ，RabbitMQ收到ACK后会从队列中删除该消息。</p><p>如果消费者处理消息失败（例如，处理过程中发生异常），可以发送拒绝（<code>nack</code>）或未确认（<code>reject</code>），根据配置，RabbitMQ可以重新将消息放回队列中，等待重新消费。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402271517763.png" alt="image.png"></p><hr><h6 id="消费者确认机制" tabindex="-1">消费者确认机制 <a class="header-anchor" href="#消费者确认机制" aria-label="Permalink to &quot;消费者确认机制&quot;">​</a></h6><p>这里再讲述一下消费者确认机制相关的内容：</p><p>消费者确认机制（Consumer Acknowledgements）在RabbitMQ中是一种保证消息被正确处理的机制。当消息从队列传递给消费者后，消费者需要对处理的结果进行反馈。如果消息被成功处理，消费者会发送一个ACK（Acknowledgement）信号给RabbitMQ，告知消息已经被成功消费，随后RabbitMQ会从队列中删除该消息。如果消费失败，消费者可以选择不发送ACK，或者显式地发送NACK（negative acknowledgement）或拒绝（reject）信号，根据配置，RabbitMQ会相应地处理这些未被确认的消息。</p><p><strong>所以说如果开启了这个机制，消息在未收到反馈消息前是会保留在队列中的</strong></p><blockquote><p>消费失败的处理</p></blockquote><p>当消费者消费失败，且没有返回ACK时，RabbitMQ会根据消息的配置来决定如何处理这条消息：</p><ol><li><strong>消息重新排队</strong>：如果消费者因为某些原因处理消息失败（例如异常退出或逻辑错误），并且没有发送ACK，那么RabbitMQ默认会将消息重新放回队列中，位置可能在队列头部或尾部，这取决于消息的<code>requeue</code>标志。如果设置为<code>true</code>，消息会被重新排队，等待其他消费者或再次被同一消费者消费。</li><li><strong>死信队列（DLX）</strong>：在某些情况下，不希望无限制地重新尝试处理消息（可能会造成死循环）。可以通过配置死信队列来处理这些&quot;无法处理&quot;的消息。如果消息消费失败，并且达到了最大重试次数（这需要在应用逻辑中实现重试机制），可以选择将消息拒绝并重新排队到死信队列中。死信队列是一个普通的RabbitMQ队列，专门用来接收这些无法处理的消息，便于后续分析和处理。</li></ol><blockquote><p>实现重试机制</p></blockquote><p>在实际应用中，通常需要在消费者侧实现消息消费的重试机制，这包括：</p><ul><li><strong>延迟重试</strong>：通过配置消息的延迟（例如，使用消息TTL和死信队列），在消息消费失败时将消息发送到一个延迟队列中，等待一段时间后再次尝试处理。</li><li><strong>重试次数限制</strong>：在消息属性中记录重试次数，每次消费失败时更新这个计数器。当重试次数达到预设的阈值后，可以将消息发送到死信队列或进行其他处理，以避免无限重试。</li></ul><p>通过这样的机制，可以灵活地控制消息的重试策略和失败处理，确保消息可以被正确处理，同时避免因重试机制不当导致的问题，如消息顺序混乱、系统资源过度占用等。</p><h5 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h5><p>如何保证消息不丢失</p><ul><li>开启生产者确认机制，确保生产者的消息能到达队列</li><li>开启持久化功能，确保消息末消费前在队列中不会丢失</li><li>开启消费者确认机制为auto,由spring确认消息处理成功后完成ack</li><li>开启消费者失数重试机别（重试次数一般设置为3），多次重试失数后将消息投递到异常交换机，交由人工处理</li></ul><p>面试者回答参考：</p><p>要求确保消息的高可用情景：实现Redis 的双写一致性采用了RabbitMQ 进行异步更新/删除操作</p><p>回答见下：👇</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402271528430.png" alt="image.png"></p><hr><h4 id="消息重复消费" tabindex="-1">消息重复消费 <a class="header-anchor" href="#消息重复消费" aria-label="Permalink to &quot;消息重复消费&quot;">​</a></h4><p>出现消息重复消费的问题一般是在网络抖动或者消息者挂掉，由于开启了消费者确认机制，导致消息重发</p><p>一般解决方式有两种：</p><ul><li>一种是每条消息设置一个唯一的标识 ID 从而避免重发消费</li><li>也可以考虑幂等性设计问题，考虑使用分布式锁、数据库锁（悲观锁、乐观锁）等，但锁会对性能有影响，使用的时候需要考虑使用</li></ul><p>一般回答可以倾向回答第一种回答。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402271532774.png" alt="image.png"></p><p>参考回答：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402271535282.png" alt="image.png"></p><h4 id="如何处理消息堆积问题" tabindex="-1">如何处理消息堆积问题 <a class="header-anchor" href="#如何处理消息堆积问题" aria-label="Permalink to &quot;如何处理消息堆积问题&quot;">​</a></h4><p>消息堆积（也称“消息积压”）是指消息队列中的消息由于未能及时消费而长时间滞留，导致队列消息数量不断增加。长期堆积会影响系统性能、延迟和可用性。</p><p>一般的处理手段：</p><p>提升消费能力、合理限流、故障隔离、定期清理、完善监控，是解决消息堆积的核心手段</p><blockquote><p>面试题：RabbitQM 如果有100万消息堆积在MQ，如何解决（消息堆积怎么解决）</p></blockquote><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240228060721.png" alt="image.png"></p><p>解决消息堆积有三种种思路：</p><ul><li>1、增加更多消费者，提高消费速度</li><li>2、在消费者内开启线程池加快消息处理速度</li><li>3、扩大队列容积，提高堆积上限，采用惰性队列 <ul><li>在声明队列的时候可以设置属性x-queue-mode为lazy,即为惰性队列</li><li>基于磁盘存储，消息上限高</li><li>性能比较稳定，但基于磁盘存储，受限于磁盘 IO,时效性会降低 · 参考回答：</li></ul></li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240228061038.png" alt="image.png"></p><h3 id="惰性队列" tabindex="-1">惰性队列 <a class="header-anchor" href="#惰性队列" aria-label="Permalink to &quot;惰性队列&quot;">​</a></h3><p>惰性队列（Lazy Queue）是 RabbitMQ 3.6 及以上版本推出的一种特殊队列类型，目的是大幅度提升<strong>海量消息场景下的性能和可靠性</strong>。它通过将消息优先存储在磁盘上，减少对内存的消耗，从而更适合消息堆积、历史消息回放、大数据批量处理等应用场景。</p><ul><li><strong>普通队列（默认模式）</strong>：RabbitMQ 会尽量把消息都存放在内存中，只有在内存压力大、或消息未被消费很久才移到磁盘。</li><li><strong>惰性队列</strong>：收到消息后直接持久化到磁盘，只有消费者需要处理时才读入内存。这大幅度降低了内存的压力，即使消息量很大也能稳定运行。</li></ul><p>不过惰性队列是在声明的时候指定配置参数，然后作为惰性队列存在，它虽然降低了内存压力，但每次消费需要从磁盘加载，<strong>单条消息延迟略高</strong>，不适合对实时性要求极高的场景。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240228060819.png" alt="image.png"></p><h3 id="死信队列" tabindex="-1">死信队列 <a class="header-anchor" href="#死信队列" aria-label="Permalink to &quot;死信队列&quot;">​</a></h3><p><strong>死信队列（Dead Letter Queue, DLQ）</strong> 是<strong>消息队列中用来存放无法被正常消费的“死信”消息的队列</strong>。 在 RabbitMQ 及其他消息队列产品中，死信队列是一种核心机制，主要用于消息可靠性、异常消息处理和系统解耦。</p><p>所谓“死信”（Dead Letter），是指在消息队列中的消息由于各种原因无法被正常消费、投递或者处理，这些消息会被队列通过特定机制转发到事先指定的<strong>死信队列</strong>中。</p><p>常见产生死信的场景包括：</p><table tabindex="0"><thead><tr><th>场景</th><th>说明</th></tr></thead><tbody><tr><td>消息被拒绝（basic.reject/basic.nack）</td><td>消费者拒绝消费消息，并且不再重新入队</td></tr><tr><td>消息过期（TTL到期）</td><td>消息在队列中存放时间超过了设置的存活时间（TTL）</td></tr><tr><td>队列达到最大长度限制</td><td>队列长度已满，新消息到来时，早期消息会被丢弃，丢弃的消息变成死信</td></tr></tbody></table><hr><h4 id="死信交换机" tabindex="-1">死信交换机 <a class="header-anchor" href="#死信交换机" aria-label="Permalink to &quot;死信交换机&quot;">​</a></h4><blockquote><p>什么是死信交换机</p></blockquote><p>死信交换机（Dead-Letter Exchange, DLX）是RabbitMQ中用于处理无法正常投递的消息的一种机制。</p><p>当消息在队列中变成死信（Dead Letter）后，可以被自动重新路由到另一个交换机，这个交换机就是所谓的死信交换机。</p><p>RabbitMQ 使用 <strong>死信交换机（Dead Letter Exchange，DLX）</strong> 将死信消息路由到另一个指定队列（即死信队列）。</p><blockquote><p>消息变成死信的情况</p></blockquote><p>消息变成死信的情况通常包括：</p><ol><li>消息被拒绝（Basic.Reject/Basic.Nack）并且设置了requeue参数为false，不重新入队。</li><li>消息TTL过期（消息设置了生存时间，超过这个时间还未被消费），超时无人消费</li><li>队列达到最大长度（队列满了，无法再添加更多消息到队列中），最早的消息可能成为死信</li></ol><blockquote><p>配置死信交换机</p></blockquote><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240228055150.png" alt="image.png"></p><p>使用死信交换机需要进行以下配置：</p><ul><li><strong>声明死信交换机</strong>：首先需要声明一个交换机作为死信交换机，可以是任何类型（Direct, Topic, Fanout等）。</li><li><strong>声明队列并指定死信交换机</strong>：在声明队列时，通过arguments参数设置<code>x-dead-letter-exchange</code>属性为死信交换机的名称。可选地，还可以设置<code>x-dead-letter-routing-key</code>来指定发送到死信交换机的消息将使用的路由键。</li><li><strong>绑定死信队列</strong>：如果需要，可以创建一个或多个专门的队列作为死信队列，并将其绑定到死信交换机上。这样，成为死信的消息就会被路由到这些队列中。</li></ul><blockquote><p>使用场景</p></blockquote><ul><li><strong>错误处理</strong>：死信交换机和死信队列常用于错误处理。当消息因为某种原因无法被正常消费时，将其路由到死信队列，后续可以对这些消息进行分析和处理。</li><li><strong>延迟消息</strong>：通过设置消息的TTL和死信交换机，可以实现延迟消息的功能。消息首先被发送到一个普通队列中，在过期后变成死信，然后被发送到死信交换机，并最终路由到最终的队列中被消费。</li><li><strong>消息重试</strong>：在处理消息时，如果因为临时的问题导致消息处理失败，可以将消息发送到死信交换机，再通过特定的逻辑将消息重新投递到原队列或另一个队列进行重试。</li></ul><p>简单示例（在Spring AMQP中配置一个死信交换机和队列）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@Bean</span></span>
<span class="line"><span>public Queue myQueue() {</span></span>
<span class="line"><span>    return QueueBuilder.durable(&quot;myQueue&quot;) //指定队列名称，并持久化</span></span>
<span class="line"><span>		    .ttl(10000)  //设置队列的超时时间，10秒</span></span>
<span class="line"><span>		    // 设置死信交换机的名称，当消息变成死信后将被路由到此交换机</span></span>
<span class="line"><span>            .withArgument(&quot;x-dead-letter-exchange&quot;, &quot;myDlxExchange&quot;) </span></span>
<span class="line"><span>            // 设置死信交换机的路由键，指定消息从死信交换机路由到死信队列时使用的路由键</span></span>
<span class="line"><span>            .withArgument(&quot;x-dead-letter-routing-key&quot;, &quot;dlx.routing.key&quot;)</span></span>
<span class="line"><span>            .build();</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>------</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 声明死信交换机</span></span>
<span class="line"><span>@Bean</span></span>
<span class="line"><span>public DirectExchange myDlxExchange() {</span></span>
<span class="line"><span>    return new DirectExchange(&quot;myDlxExchange&quot;);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 声明死信队列</span></span>
<span class="line"><span>@Bean</span></span>
<span class="line"><span>public Queue myDlxQueue() {</span></span>
<span class="line"><span>	// 使用QueueBuilder构建一个持久化的队列&quot;myDlxQueue&quot;，这个队列用于接收死信消息</span></span>
<span class="line"><span>    return QueueBuilder.durable(&quot;myDlxQueue&quot;).build();</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 将死信队列绑定到死信交换机</span></span>
<span class="line"><span>@Bean</span></span>
<span class="line"><span>public Binding myDlxBinding() {</span></span>
<span class="line"><span>	// 使用 BindingBuilder 将死信队列&quot;myDlxQueue&quot;绑定到死信交换机&quot;myDlxExchange&quot; </span></span>
<span class="line"><span>	// 绑定键为&quot;dlx.routing.key&quot;，表示只有路由键匹配此值的消息才会被路由到&quot;myDlxQueue&quot;队列</span></span>
<span class="line"><span>    return BindingBuilder.bind(myDlxQueue()).to(myDlxExchange()).with(&quot;dlx.routing.key&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这个配置声明了一个队列<code>myQueue</code>和一个死信交换机<code>myDlxExchange</code>，以及一个死信队列<code>myDlxQueue</code>。当<code>myQueue</code>中的消息变成死信后，它们会被路由到<code>myDlxQueue</code>中。</p><p>总之，死信交换机提供了一种有效的方式来处理RabbitMQ中无法正常消费的消息，使得系统能够更加健壮和可靠。</p><h4 id="ttl" tabindex="-1">TTL <a class="header-anchor" href="#ttl" aria-label="Permalink to &quot;TTL&quot;">​</a></h4><p>TTL（Time-To-Live）是一种设置数据存活时间的机制，在RabbitMQ中，可以用来控制消息或队列的存活时间。</p><p>如果一个队列中的消息TTL结束仍未消费，则会变为死信， ttl 超时分为两种情况：</p><ul><li>1、消息所在的队列设置了存活时间</li><li>2、消息本身设置了存活时间</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240228055549.png" alt="image.png"></p><blockquote><p>消息TTL</p></blockquote><ul><li><strong>消息TTL</strong>是指一条消息在队列中可以存活的最大时间。如果消息在队列中的存活时间超过了设置的TTL，它将变成死信（Dead Letter）。对于未及时消费的消息，这是一种有效的过期策略。</li><li>在RabbitMQ中，消息TTL可以在发送消息时通过设置消息属性中的<code>expiration</code>字段来指定，单位是毫秒。例如，将<code>expiration</code>设置为<code>60000</code>，意味着消息的TTL为60秒。</li></ul><p>示例代码：</p><p>设置消息TTL</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AMQP.BasicProperties props = new AMQP.BasicProperties.Builder()</span></span>
<span class="line"><span>        .expiration(&quot;60000&quot;) // 消息TTL设置为60000毫秒（60秒）</span></span>
<span class="line"><span>        .build();</span></span>
<span class="line"><span>channel.basicPublish(&quot;&quot;, &quot;myQueue&quot;, props, message.getBytes());</span></span></code></pre></div><blockquote><p>队列TTL</p></blockquote><ul><li><strong>队列TTL</strong>是指队列中的所有消息的统一存活时间。不同于为每条消息单独设置TTL，队列TTL为队列中所有消息设定了统一的最大存活时间。</li><li>队列TTL是在声明队列时通过队列的<code>arguments</code>参数设置的，使用<code>x-message-ttl</code>属性来指定，单位也是毫秒。</li></ul><p>设置队列TTL</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Map&lt;String, Object&gt; args = new HashMap&lt;String, Object&gt;();</span></span>
<span class="line"><span>args.put(&quot;x-message-ttl&quot;, 60000); // 队列中所有消息的TTL设置为60000毫秒（60秒）</span></span>
<span class="line"><span>channel.queueDeclare(&quot;myQueue&quot;, false, false, false, args);</span></span></code></pre></div><hr><p>注意事项：</p><ul><li>如果队列和消息都设置了TTL，以较短的那个TTL为准。</li><li>设置了TTL的消息，如果在TTL到期时还没有被消费，会被RabbitMQ自动丢弃或发送到设置的死信交换机。</li><li>消息的TTL从它被推送到队列的那一刻开始计算，而不是从它被消费者接收的那一刻开始。</li></ul><hr><h3 id="延迟队列" tabindex="-1">延迟队列 <a class="header-anchor" href="#延迟队列" aria-label="Permalink to &quot;延迟队列&quot;">​</a></h3><p>延迟队列实现的几种方式：</p><h4 id="利用-ttl-死信队列实现延迟队列" tabindex="-1">利用 TTL + 死信队列实现延迟队列 <a class="header-anchor" href="#利用-ttl-死信队列实现延迟队列" aria-label="Permalink to &quot;利用 TTL + 死信队列实现延迟队列&quot;">​</a></h4><p>实现思路</p><ul><li>普通队列设置消息 TTL（Time-To-Live，存活时间），即消息在队列内存活的时间。</li><li>TTL 到期后消息会被 RabbitMQ 刪除并变成“死信”，转入<strong>指定的死信交换机</strong>和死信队列。</li><li>消费者监听死信队列，消费消息，实现延迟效果。</li></ul><p>RabbitMQ 的延迟队列是通过死信交换机 + TTL （生存时间）来实现的；</p><ul><li>延迟队列：进入队列的消息会被延迟消费的队列</li></ul><p>延迟队列的使用场景较多，比如：超市订单、限时优惠、定时发布等</p><hr><h4 id="使用-rabbitmq-官方插件实现延迟队列" tabindex="-1">使用 RabbitMQ 官方插件实现延迟队列 <a class="header-anchor" href="#使用-rabbitmq-官方插件实现延迟队列" aria-label="Permalink to &quot;使用 RabbitMQ 官方插件实现延迟队列&quot;">​</a></h4><p>RabbitMQ 提供了 <strong>rabbitmq-delayed-message-exchange</strong> 插件，可以直接实现消息延迟投递，无需借助死信队列。</p><p>实现方式</p><ul><li>安装插件后，声明一种特殊交换机 <code>&quot;x-delayed-message&quot;</code> 类型。</li><li>发送消息时通过 <code>headers</code> 设置延迟时间，消息到达队列时才被消费</li></ul><hr><p>在 RabbitMQ 中，延迟队列的使用是有一个插件：叫做：DelayExchange</p><p>地址在官方插件社区</p><p>插件下载地址： <a href="https://github.com/rabbitmq/rabbitmq-delayed-message-exchange" target="_blank" rel="noreferrer">https://github.com/rabbitmq/rabbitmq-delayed-message-exchange</a></p><p>使用示例：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240228060325.png" alt="image.png"></p><hr>`,128)])])}const g=e(l,[["render",i]]);export{b as __pageData,g as default};
